import math, numpy as np, itertools
c=3e8; f=2.4e9; d0=1.0; n=3.0; tx=20.0; minr=-75.0
PL0 = 20*math.log10(4*math.pi*d0*f/c)
APS=[(50.0,100.0),(150.0,100.0)]
W=H=200.0; SR=(1.0,5.0); STEPS=500; SEED=42

def rssi(pos, ap):
    d = math.hypot(pos[0]-ap[0], pos[1]-ap[1])
    if d <= 0: return tx
    return tx - (PL0 + 10*n*math.log10(d/d0))

def trace_gen(start, steps, target_first=True, arrive_lt=True, include_start=False,
              speed_each_step=False, xy_order=True):
    rng = np.random.RandomState(SEED)
    def tgt():
        if xy_order:
            return (rng.uniform(0,W), rng.uniform(0,H))
        else:
            y=rng.uniform(0,H); x=rng.uniform(0,W); return (x,y)
    pos=tuple(start); out=[]
    if include_start: out.append(pos)
    if target_first:
        target=tgt(); speed=rng.uniform(*SR)
    else:
        speed=rng.uniform(*SR); target=tgt()
    while len(out) < (steps + (1 if include_start else 0)):
        dx=target[0]-pos[0]; dy=target[1]-pos[1]
        dist=math.hypot(dx,dy)
        arrived = (dist < speed) if arrive_lt else (dist <= speed)
        if arrived or dist==0:
            pos=target
            if target_first:
                target=tgt(); speed=rng.uniform(*SR)
            else:
                speed=rng.uniform(*SR); target=tgt()
        else:
            pos=(pos[0]+speed*dx/dist, pos[1]+speed*dy/dist)
            if speed_each_step: speed=rng.uniform(*SR)
        out.append(pos)
    return out

def analyse(tr):
    assoc=[]
    for p in tr:
        best=None; bestr=-1e9
        for i,ap in enumerate(APS):
            r=rssi(p,ap)
            if r>=minr and r>bestr:
                bestr=r; best=i
        assoc.append(best)
    # conventions
    ho_strict=0   # prev non-None and cur non-None and differ (immediate previous)
    ho_lastknown=0 # prev = last known non-None AP
    ho_anychange=0 # any change incl to/from None
    ho_incl_initial=0 # cur non-None and cur != immediate prev (prev may be None)
    prev=None; last=None
    for i,a in enumerate(assoc):
        if i>0:
            if prev is not None and a is not None and a!=prev: ho_strict+=1
            if a is not None and a!=prev: ho_incl_initial+=1
            if a!=prev: ho_anychange+=1
        else:
            if a is not None: ho_incl_initial+=1  # initial association counts
        if a is not None:
            if last is not None and a!=last: ho_lastknown+=1
            last=a
        prev=a
    covered=sum(1 for a in assoc if a is not None)
    pct=100.0*covered/len(assoc)
    return dict(strict=ho_strict, lastknown=ho_lastknown, anychange=ho_anychange,
                incl_initial=ho_incl_initial, covered=covered, n=len(assoc), pct=pct)

print("=== CANONICAL: start=(100,100) center, target-then-speed, dist<speed arrival, 500 pts excl start ===")
tr = trace_gen((100.0,100.0), STEPS)
r = analyse(tr); print(r, ' pct printed %.2f'%r['pct'])
print('first 5 positions:', [(round(x,3),round(y,3)) for x,y in tr[:5]])
print()
for start in [(100.0,100.0),(0.0,0.0),(50.0,100.0),(10.0,10.0),(100.0,0.0)]:
    tr=trace_gen(start,STEPS); r=analyse(tr)
    print(f'start={start}: handovers strict={r["strict"]} lastknown={r["lastknown"]} anychange={r["anychange"]} inclinit={r["incl_initial"]}  cov={r["covered"]}/{r["n"]} = {r["pct"]:.2f}%')
print()
print("variants (start=100,100):")
for kw in [dict(arrive_lt=False), dict(include_start=True), dict(target_first=False), dict(xy_order=False), dict(speed_each_step=True)]:
    tr=trace_gen((100.,100.),STEPS,**kw); r=analyse(tr)
    print(f'{kw}: strict={r["strict"]} lastknown={r["lastknown"]} anychange={r["anychange"]} cov={r["covered"]}/{r["n"]}={r["pct"]:.2f}%')
