import math, numpy as np, itertools
c=3e8; f=2.4e9; n=3.0; tx=20.0; minr=-75.0
PL0=20*math.log10(4*math.pi*f/c)
APS=[(50.,100.),(150.,100.)]; W=H=200.; SR=(1.,5.); STEPS=500
def rssi(p,ap):
    d=math.hypot(p[0]-ap[0],p[1]-ap[1])
    return tx if d<=0 else tx-(PL0+10*n*math.log10(d))
def assoc_seq(tr):
    a=[]
    for p in tr:
        best=None;br=-1e9
        for i,ap in enumerate(APS):
            r=rssi(p,ap)
            if r>=minr and r>br: br=r;best=i
        a.append(best)
    return a
def gen(mode, start=(100.,100.), steps=STEPS, seed=42):
    rng=np.random.RandomState(seed); pos=start; out=[]
    def tgt():
        if mode=='xy': return (rng.uniform(0,W), rng.uniform(0,H))
        if mode=='vec2': v=rng.uniform(0,[W,H]); return (v[0],v[1])
        if mode=='rand2': v=rng.rand(2); return (v[0]*W, v[1]*H)
        if mode=='uniform_size2': v=rng.uniform(0,W,2); return (v[0],v[1])
    target=tgt(); speed=rng.uniform(*SR)
    for _ in range(steps):
        dx=target[0]-pos[0]; dy=target[1]-pos[1]; d=math.hypot(dx,dy)
        if d<speed:
            pos=target; target=tgt(); speed=rng.uniform(*SR)
        else: pos=(pos[0]+speed*dx/d,pos[1]+speed*dy/d)
        out.append(pos)
    return out
for mode in ['xy','vec2','rand2','uniform_size2']:
    a=assoc_seq(gen(mode))
    strict=sum(1 for i in range(1,len(a)) if a[i] is not None and a[i-1] is not None and a[i]!=a[i-1])
    last=None; lk=0
    for x in a:
        if x is not None:
            if last is not None and x!=last: lk+=1
            last=x
    cov=100*sum(x is not None for x in a)/len(a)
    print(f'{mode:14s} strict={strict} lastknown={lk} cov={cov:.2f}')
print()
a=assoc_seq(gen('xy'))
# run-length encode
rle=[(k, len(list(g))) for k,g in itertools.groupby(a)]
print('RLE of assoc (AP index or None, run length), canonical:')
print(rle)
